<script>
  import { init } from '../../utils'
  import Radio from './Radio.svelte'

  let {
    legend: legendProp = '',
    legendClass: legendClassProp = '',
    label = '',
    labelClass = '',
    items = $bindable([]),
    radios = $bindable([]),
    ref = $bindable(null),
    checked = $bindable(null),
    class: klass = '',
    radiosClass = '',
    icon,
    iconClass = '',
    name,
    disabled = null,
    readonly = null,
    ...rest
  } = $props()

  let legend = $state('')
  let legendClass = $state('')

  init(() => {
    legend = legendProp
    legendClass = legendClassProp

    // Let users use either items or radios
    if (radios.length) items = radios
    if (!items.length && !radios.length) {
      console.warn('No radios or items provided to <Radios />')
    }

    // Let users use either label or legend
    if (label) legend = label
    if (labelClass) legendClass = labelClass

    items = items.map(radio => {
      if (typeof radio === 'string') radio = { value: radio }
      return { ref: null, ...radio }
    })

    checked = items.find(radio => radio.checked)?.value
  })

  const radioProps = $derived({ icon, iconClass, disabled, readonly })
</script>

<fieldset {...rest} bind:this={ref} class="fieldset {klass}">
  {#if legend}
    <legend class="legend {legendClass}">{legend}</legend>
  {/if}

  <div class="radios {radiosClass}">
    {#each items as radio (radio.value)}
      <Radio
        {...radioProps}
        {...radio}
        {name}
        bind:group={checked}
        bind:ref={radio.ref}
      />
    {/each}
  </div>
</fieldset>
